apply.script:
$Path = Resolve-Path -Path "$Env:ProgramFiles (x86)\Microsoft\Edge\Application\*\Installer\setup.exe" -ErrorAction SilentlyContinue | Select-Object -Last 1

      if ($Path -and (Test-Path $Path)) {
          $proc = Start-Process -FilePath $Path -ArgumentList "--uninstall --system-level --force-uninstall --delete-profile" -Wait -PassThru
          if ($proc.ExitCode -ne 0) { throw "setup.exe failed with exit code $($proc.ExitCode)" }
      }

$setup = Join-Path $Env:SystemRoot "System32\OneDriveSetup.exe"
      if (Test-Path $setup) {
          $proc = Start-Process -FilePath $setup -ArgumentList '/uninstall' -Wait -PassThru
          if ($proc.ExitCode -ne 0) { throw "OneDriveSetup.exe failed with exit code $($proc.ExitCode)" }
      }
      Stop-Process -Name FileCoAuth,OneDrive -Force -ErrorAction SilentlyContinue

$AppxPackage = Get-AppxPackage MicrosoftWindows.Client.CoreAI -ErrorAction SilentlyContinue
      $Appx = if ($AppxPackage) { $AppxPackage.PackageFullName } else { $null }

      $user = Get-LocalUser $Env:UserName -ErrorAction SilentlyContinue
      if ($user -and $Appx) {
          $Sid = $user.Sid.Value
          New-Item "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\EndOfLife\$Sid\$Appx" -Force -ErrorAction SilentlyContinue | Out-Null
      }

      Get-AppxPackage -AllUsers "*Copilot*" -ErrorAction SilentlyContinue | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
      winget uninstall -e --name "Copilot" --silent --force --accept-source-agreements 2>$null
      if ($LASTEXITCODE -ne 0 -and $LASTEXITCODE -ne 3010 -and $LASTEXITCODE -ne -1978335135 -and $LASTEXITCODE -ne -1978335189 -and $LASTEXITCODE -ne -1978335212) { throw "winget failed with exit code $LASTEXITCODE" }
      Get-AppxPackage -AllUsers Microsoft.MicrosoftOfficeHub -ErrorAction SilentlyContinue | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue

      if ($Appx) {
          Remove-AppxPackage $Appx -ErrorAction SilentlyContinue
      }

      if (Get-Service -Name WSAIFabricSvc -ErrorAction SilentlyContinue) {
          Set-Service -Name WSAIFabricSvc -StartupType Disabled -ErrorAction SilentlyContinue
      }
      Disable-WindowsOptionalFeature -FeatureName Recall -Online -NoRestart -ErrorAction SilentlyContinue

      Write-Host "Windows AI Disabled"

$RazerPath = "$Env:SystemRoot\Installer\Razer"

      if (Test-Path $RazerPath) {
        Remove-Item $RazerPath\* -Recurse -Force
      } else {
        New-Item -Path $RazerPath -ItemType Directory
      }

      icacls $RazerPath /deny "*S-1-1-0:(W)"

Stop-Process -Name "logi_download_assistant" -Force -ErrorAction SilentlyContinue

      $ProgramFiles64 = if ($Env:ProgramW6432) { $Env:ProgramW6432 } else { $Env:ProgramFiles }
      $LogiPath = "$ProgramFiles64\LogiDownloadAssistant"

      if (Test-Path $LogiPath) {
        Remove-Item $LogiPath\* -Recurse -Force -ErrorAction SilentlyContinue
      } else {
        New-Item -Path $LogiPath -ItemType Directory -ErrorAction SilentlyContinue
      }

      icacls $LogiPath /deny "*S-1-1-0:(W)" | Out-Null

undo.script:
$ProgramFiles64 = if ($Env:ProgramW6432) { $Env:ProgramW6432 } else { $Env:ProgramFiles }
      $LogiPath = "$ProgramFiles64\LogiDownloadAssistant"

      if (Test-Path $LogiPath) {
        icacls $LogiPath /remove:d "*S-1-1-0" -ErrorAction SilentlyContinue | Out-Null
      }
